# AUTO-GENERATED by _add_social_link_and_gating.py
"""
완성 리포트 엔드포인트.

파이프라인:
  calculate_saju()          → 사주 계산 (억부 간이판 기준)
  build_semantic_profile()  → 언어 중립 태그
  generate_full_report()    → 자연어 리포트 (en/ko)
  apply_entitlement_gate()  → 티어별 섹션 게이팅

인증:
  - 헤더 없음 → tier="preview" (게이팅 없음, 하위호환/CLI)
  - 인증됨   → user.tier ("free" 면 게이팅)
  - SAJU_REQUIRE_AUTH_FOR_REPORT=true 면 헤더 없을 때 401
"""
import os
import logging

from fastapi import APIRouter, Depends, HTTPException

from app.engine.calculator import calculate_saju
from app.semantic.tagger import build_semantic_profile
from app.services.content_writer import generate_full_report
from app.services.entitlements import apply_entitlement_gate
from app.auth.dependencies import get_current_user_optional
from app.schemas.saju import ReportRequest, ReportResponse

logger = logging.getLogger(__name__)
router = APIRouter()


def _require_auth() -> bool:
    v = os.environ.get("SAJU_REQUIRE_AUTH_FOR_REPORT", "").lower()
    return v in ("1", "true", "yes", "on")


@router.post("/report", response_model=ReportResponse)
def api_generate_report(
    payload: ReportRequest,
    current_user: dict | None = Depends(get_current_user_optional),
):
    """
    생년월일시로 완성된 사주 리포트를 생성합니다.
    """
    if _require_auth() and current_user is None:
        raise HTTPException(
            status_code=401,
            detail=(
                "Authentication required. "
                "Create a session at /api/v1/auth/anonymous."
            ),
        )

    try:
        saju_result = calculate_saju(
            birth_date=payload.birth_date,
            birth_time=payload.birth_time,
            birth_time_mode=payload.birth_time_mode,
            timezone_str=payload.timezone_str,
            longitude=payload.longitude,
            correction_mode=payload.correction_mode,
            jasi_boundary=payload.jasi_boundary,
            gender=payload.gender,
            target_year=payload.target_year,
            dst_fold=payload.dst_fold,
            birth_location=payload.birth_location,
        )
    except (ValueError, TypeError) as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception:
        logger.exception("calculate_saju failed inside /report")
        raise HTTPException(status_code=500, detail="Calculation error.")

    try:
        profile = build_semantic_profile(saju_result)
        uid = current_user.get('id') if current_user else None
        report = generate_full_report(profile, lang=payload.lang, user_id=uid)
    except Exception:
        logger.exception("Report generation failed")
        raise HTTPException(
            status_code=500,
            detail="Report generation failed. Please try again or contact support.",
        )

    tier = "free" if current_user is None else (current_user.get("tier") or "free")
    report = apply_entitlement_gate(report, tier)
    return {"report": report}
